#include <stdio.h>

int main() {
    int a[] = {12, 35, 1, 10, 34, 1};
    int first = -1, second = -1;
    for (int i = 0; i < 6; i++) {
        if (a[i] > first) {
            second = first;
            first = a[i];
        } else if (a[i] > second && a[i] != first) {
            second = a[i];
        }
    }
    printf("Largest: %d\nSecond largest: %d\n", first, second);
    return 0;
}
